/**
 * Growth OS — Ensure the private 'internal-expenses' storage bucket exists.
 *
 * Internal Expense Tracker stores original receipts/invoices here. The bucket
 * is PRIVATE (no public URLs) — files are only reachable through short-lived
 * signed URLs generated by the admin-gated API. Run once after deploy:
 *
 *   node scripts/ensure-internal-expenses-bucket.js
 *
 * Idempotent: safe to run repeatedly.
 */

require('dotenv').config();
const { createClient } = require('@supabase/supabase-js');

const BUCKET = process.env.INTERNAL_EXPENSES_BUCKET || 'internal-expenses';

async function main() {
  const url = process.env.SUPABASE_URL;
  const key = process.env.SUPABASE_SERVICE_KEY;
  if (!url || !key) {
    console.error('Missing SUPABASE_URL or SUPABASE_SERVICE_KEY in .env');
    process.exit(1);
  }
  const supabase = createClient(url, key);

  const { data: existing, error: listErr } = await supabase.storage.listBuckets();
  if (listErr) {
    console.error('Failed to list buckets:', listErr.message);
    process.exit(1);
  }

  if (existing.some((b) => b.name === BUCKET)) {
    console.log(`✓ Bucket "${BUCKET}" already exists (private).`);
    return;
  }

  const { error: createErr } = await supabase.storage.createBucket(BUCKET, {
    public: false,
    fileSizeLimit: '15MB',
    allowedMimeTypes: [
      'application/pdf',
      'image/jpeg',
      'image/png',
      'image/heic',
      'image/heif',
      'image/webp',
    ],
  });
  if (createErr) {
    console.error(`Failed to create bucket "${BUCKET}":`, createErr.message);
    process.exit(1);
  }
  console.log(`✓ Created PRIVATE bucket "${BUCKET}".`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
